            where: T("Controlador Git → ESTE servicio → NativeGitRunner → git nativo / remoto.", "Git controller → THIS service → NativeGitRunner → native git / remote."),
            recv: T("Operación + perfil, rama, rama origen, mensaje de commit, estrategia de pull; o ruta y contenido resuelto de un conflicto.", "Operation + profile, branch, source branch, commit message, pull strategy; or path and resolved content of a conflict."), prod: T("RemoteGitOperationResult (éxito, rama, ahead/behind, conflictos, cambios, mensaje), árbol de repositorio o vista de conflicto.", "RemoteGitOperationResult (success, branch, ahead/behind, conflicts, changes, message), repository tree or conflict view."),
            calls: ["er_git_runner", { n: "ProjectApplicationService", d: T("Da el directorio del proyecto activo.", "Gives the active project directory.") }, { n: "RemoteStorageCredentialResolver", d: T("Credenciales del perfil para fetch/pull/push.", "Profile credentials for fetch/pull/push.") }, "er_provider_type"], usedBy: ["er_git_controller"],
